function MillSailClothGrommetMaker.init() MillSailClothGrommetMaker.ironStock=14; MillSailClothGrommetMaker.bronzeStock=12; MillSailClothGrommetMaker.woodStock=12; MillSailClothGrommetMaker.leatherStock=8; MillSailClothGrommetMaker.silverStock=8; MillSailClothGrommetMaker.goldStock=6; MillSailClothGrommetMaker.jewelStock=4; MillSailClothGrommetMaker.pearlStock=4; MillSailClothGrommetMaker.productStock={}; MillSailClothGrommetMaker.buildings={}; MillSailClothGrommetMaker.maker=nil; MillSailClothGrommetMaker.activeMaking={}; MillSailClothGrommetMaker.totalProducts=0; MillSailClothGrommetMaker.dayTimer=0; print("[MillSailClothGrommetMaker] Royal Mill Sail Cloth Grommet Maker System initialized (6 products, 4 buildings)") end
function MillSailClothGrommetMaker.hireMaker(n,s) s=s or math.random(55,90); local c=575+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; MillSailClothGrommetMaker.maker={name=n or ("Obročnik "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Obročnik najet: %s (spretnost: %d)",MillSailClothGrommetMaker.maker.name,s),"success") end; return true end
function MillSailClothGrommetMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function MillSailClothGrommetMaker.build(id) local ok,e=MillSailClothGrommetMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(MillSailClothGrommetMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function MillSailClothGrommetMaker.getQualityBonus() local b=0; for _,bd in ipairs(MillSailClothGrommetMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function MillSailClothGrommetMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and MillSailClothGrommetMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and MillSailClothGrommetMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and MillSailClothGrommetMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and MillSailClothGrommetMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and MillSailClothGrommetMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and MillSailClothGrommetMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and MillSailClothGrommetMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and MillSailClothGrommetMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #MillSailClothGrommetMaker.buildings==0 then return false,"Potrebna obročna delavnica" end; if not MillSailClothGrommetMaker.maker then return false,"Potreben obrocnik" end; return true end
function MillSailClothGrommetMaker.make(pt,qty) qty=qty or 1; local ok,e=MillSailClothGrommetMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then MillSailClothGrommetMaker.ironStock=MillSailClothGrommetMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then MillSailClothGrommetMaker.bronzeStock=MillSailClothGrommetMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then MillSailClothGrommetMaker.woodStock=MillSailClothGrommetMaker.woodStock-d.woodCost*qty end; if d.leatherCost then MillSailClothGrommetMaker.leatherStock=MillSailClothGrommetMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then MillSailClothGrommetMaker.silverStock=MillSailClothGrommetMaker.silverStock-d.silverCost*qty end; if d.goldCost then MillSailClothGrommetMaker.goldStock=MillSailClothGrommetMaker.goldStock-d.goldCost*qty end; if d.jewelCost then MillSailClothGrommetMaker.jewelStock=MillSailClothGrommetMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then MillSailClothGrommetMaker.pearlStock=MillSailClothGrommetMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if MillSailClothGrommetMaker.maker then t=math.max(1,t-math.floor(MillSailClothGrommetMaker.maker.skill/13)) end; table.insert(MillSailClothGrommetMaker.activeMaking,{id="millsailclothgrommet_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function MillSailClothGrommetMaker.completeMaking(m) local q=1.0+(MillSailClothGrommetMaker.getQualityBonus()/100); if MillSailClothGrommetMaker.maker then q=q+(MillSailClothGrommetMaker.maker.skill/140) end; q=math.min(2.5,q); MillSailClothGrommetMaker.productStock[m.productType]=(MillSailClothGrommetMaker.productStock[m.productType] or 0)+m.quantity; MillSailClothGrommetMaker.totalProducts=MillSailClothGrommetMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if MillSailClothGrommetMaker.maker then MillSailClothGrommetMaker.maker.itemsMade=MillSailClothGrommetMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then MillSailClothGrommetMaker.maker.skill=math.min(100,MillSailClothGrommetMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Obroč izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"millsailclothgrommet.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function MillSailClothGrommetMaker.update(dt) if not _G.state then return end; MillSailClothGrommetMaker.dayTimer=MillSailClothGrommetMaker.dayTimer+dt; if MillSailClothGrommetMaker.dayTimer>=30 then MillSailClothGrommetMaker.dayTimer=0; for i=#MillSailClothGrommetMaker.activeMaking,1,-1 do local m=MillSailClothGrommetMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then MillSailClothGrommetMaker.completeMaking(m); table.remove(MillSailClothGrommetMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(MillSailClothGrommetMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if MillSailClothGrommetMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function MillSailClothGrommetMaker.getStats() return {ironStock=MillSailClothGrommetMaker.ironStock,bronzeStock=MillSailClothGrommetMaker.bronzeStock,woodStock=MillSailClothGrommetMaker.woodStock,leatherStock=MillSailClothGrommetMaker.leatherStock,silverStock=MillSailClothGrommetMaker.silverStock,goldStock=MillSailClothGrommetMaker.goldStock,jewelStock=MillSailClothGrommetMaker.jewelStock,pearlStock=MillSailClothGrommetMaker.pearlStock,productStock=MillSailClothGrommetMaker.productStock,numBuildings=#MillSailClothGrommetMaker.buildings,hasMaker=MillSailClothGrommetMaker.maker~=nil,makerName=MillSailClothGrommetMaker.maker and MillSailClothGrommetMaker.maker.name or "—",makerSkill=MillSailClothGrommetMaker.maker and MillSailClothGrommetMaker.maker.skill or 0,activeMaking=#MillSailClothGrommetMaker.activeMaking,totalProducts=MillSailClothGrommetMaker.totalProducts} end
